    // ─────────────────────────────────────────────────────────────────────────

    /// n=3 where two values are the same and one differs: degenerate but
    /// should produce a valid W in [0, 1].
    #[test]
    fn bug_hunt_shapiro_n3_two_identical() {
        let x = [1.0, 1.0, 100.0];
        let w = shapiro_w_scalar(&x);
        assert!(
            w.is_finite() && w >= 0.0 && w <= 1.0,
            "n=3 with 2 identical values: W should be in [0,1], got {w}"
        );
    }

    /// n=3 with exponentially different magnitudes: should still be valid.
    #[test]
    fn bug_hunt_shapiro_n3_extreme_magnitude_differences() {
        let x = [1e-100, 1.0, 1e100];
        let w = shapiro_w_scalar(&x);
        assert!(
            w.is_finite() && w >= 0.0 && w <= 1.0,
            "n=3 extreme magnitudes: W should be in [0,1], got {w}"
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Shapiro-Wilk: W > 1 possible for certain inputs?
    // ─────────────────────────────────────────────────────────────────────────

    /// The Shapiro-Wilk statistic should satisfy 0 <= W <= 1 for all non-degenerate
    /// inputs. Test with various n to check if W ever exceeds 1.
    #[test]
    fn bug_hunt_shapiro_w_never_exceeds_one() {
        // Check many different sizes
        for n in 3..=30 {
            let x: Vec<f64> = (0..n).map(|i| (i as f64).powi(2) + 0.1 * (i as f64)).collect();
            let w = shapiro_w_scalar(&x);
            if w.is_finite() {
                assert!(
                    w <= 1.0 + 1e-10,
                    "W should never exceed 1.0: n={n}, W={w}"
                );
                assert!(
                    w >= 0.0,
                    "W should never be negative: n={n}, W={w}"
                );
            }
        }
    }

